import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const i=JSON.parse('{"title":"10.5 精华题与补充题","description":"","frontmatter":{},"headers":[],"relativePath":"10-标准化与知识产权/91-精华题与补充题.md","filePath":"10-标准化与知识产权/91-精华题与补充题.md"}'),e={name:"10-标准化与知识产权/91-精华题与补充题.md"};function a(p,t,g,_,B,c){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_10-5-精华题与补充题" tabindex="-1">10.5 精华题与补充题 <a class="header-anchor" href="#_10-5-精华题与补充题" aria-label="Permalink to &quot;10.5 精华题与补充题&quot;">​</a></h1><p><strong>1.</strong> 构成我国保护计算机软件著作权的两个基本法律文件是（ ）。 A. 《著作权法》和《计算机软件保护条例》 B. 《著作权法》和《专利法》 C. 《商标法》和《计算机软件保护条例》 D. 《著作权法》和《标准化法》</p><p><strong>2.</strong> 国际上保护计算机软件知识产权所采用的主要方式是实施（ ）。 A. 合同法 B. 物权法 C. 版权法 D. 刑法</p><p><strong>3.</strong> 某企业的核心技术配方从未申请专利、也未发表，企业通过内部保密制度与竞业协议长期保密。关于该技术配方，下列说法正确的是（ ）。 A. 属于商业秘密，保护期为 20 年 B. 属于商业秘密，只要保密措施有效就持续受保护，他人独立研发出同样配方不侵权 C. 属于商业秘密，保护期为 10 年 D. 因未公开，不受任何法律保护</p><p><strong>4.</strong> 关于软件著作权登记，下列说法正确的是（ ）。 A. 登记是取得软件著作权的法定前提 B. 软件著作权自开发完成之日起产生，登记只是初步证明手段 C. 未经登记的软件不受法律保护 D. 登记后软件著作权才自动产生</p><p><strong>5.</strong> 我国著作权法中，发表权的保护期为（ ）。 A. 永久保护 B. 作者终生及其死亡后 50 年 C. 作品完成后 30 年 D. 作者终生及其死亡后 20 年</p><p><strong>6.</strong> 标准实施后需要进行复审，我国标准的复审周期一般不超过（ ）。 A. 3 年 B. 5 年 C. 8 年 D. 10 年</p><p><strong>7.</strong> 某公司开发的系统需要与另一厂商的老系统对接，但对方拒绝提供软件接口文档，且通过正当途径无法获得该接口的必要信息。该公司为实现兼容而对对方软件进行反编译。该行为（ ）。 A. 构成侵权，反编译一律侵权 B. 不构成侵权，属于软件保护条例规定的为兼容性需要的例外情形 C. 构成侵权，除非事先取得专利许可 D. 不构成侵权，因为软件本无著作权</p><p><strong>8.</strong> 下列标准代号中，属于<strong>强制性</strong>国家标准的是（ ）。 A. GB/T 22239 B. GB 18030 C. GB/Z 20986 D. SJ/T 11234</p><hr><h2 id="补充题-四大权利对比-标准代号-6-道" tabindex="-1">补充题（四大权利对比 + 标准代号 6 道） <a class="header-anchor" href="#补充题-四大权利对比-标准代号-6-道" aria-label="Permalink to &quot;补充题（四大权利对比 + 标准代号 6 道）&quot;">​</a></h2><p><strong>1.</strong> 关于四种知识产权的取得方式，下列说法正确的是（ ）。 A. 著作权、商标权均须登记或注册后才能取得 B. 专利权、商标权须经申请/注册取得，著作权自动产生，商业秘密靠保密措施维持 C. 商业秘密须向主管部门申请登记后方可取得 D. 四种知识产权都实行&quot;先申请原则&quot;</p><p><strong>2.</strong> 某企业开发出一种新型电路板，产品一旦上市即可被对手拆解分析（可被逆向）。该企业希望获得最强独占（即使别人独立研究出同样的方案也不得实施）。下列做法<strong>最合理</strong>的是（ ）。 A. 当作商业秘密长期保密，因为保密期无上限 B. 申请发明专利，用&quot;公开换独占&quot;防止他人独立实施 C. 只申请商标注册 D. 不采取任何保护措施</p><p><strong>3.</strong> 关于标准代号 <code>T/ABC 001</code>，下列说法正确的是（ ）。 A. 它是推荐性国家标准，ABC 为行业代码 B. 它是团体标准，T 在首、后接团体代号 C. 它是企业标准，T 表示推荐 D. 它是强制性标准，必须执行</p><p><strong>4.</strong> 看到标准号自 <code>GB/T 19001</code>，其所属层级与性质是（ ）。 A. 强制性国家标准 B. 推荐性国家标准 C. 团体标准 D. 行业标准</p><p><strong>5.</strong> 四种知识产权中，<strong>允许他人独立研究或通过反向工程获得同样成果而不侵权</strong>的是（ ）。 A. 著作权 B. 专利权 C. 商标权 D. 商业秘密</p><p><strong>6.</strong> 关于商标权保护期的续展与起算，下列说法正确的是（ ）。 A. 自申请日起算，期满自动续展 B. 自核准注册之日起算 10 年，期满前可续展，每次 10 年、次数不限 C. 自首次使用之日起算 D. 自登记之日起算，且只能续展 3 次</p><hr>',18)])])}const A=o(e,[["render",a]]);export{i as __pageData,A as default};
